{"command": "# Search for patterns that might indicate VM opcode dispatch
# Look for movzx, test, or cmp instructions that check a register value

objdump -d /app/validator 2>/dev/null | grep -E "mov.*%al|%eax.*%al|test.*%al|cmp.*%al|switch|jump" | head -50"}

{"command": "# Look for XOR with memory operand (0f a3 is xor with r/m32)
# Pattern: 0f a3 xx xx xx xx - XOR memory with register

objdump -d /app/validator 2>/dev/null | grep "0f a3" | head -20"}
